#!/usr/bin/env python3
"""Build the dated source review from its immutable evidence snapshot."""
import html,json
from pathlib import Path
R=Path(__file__).resolve().parent
d=json.loads((R/'source-audit.json').read_text())
E=lambda x:html.escape(str(x),quote=True)
def link(url,label):return f'<a href="{E(url)}" target="_blank" rel="noopener noreferrer">{E(label)} ↗</a>'
def table(head,rows):return '<div class="table-scroll" tabindex="0"><table><thead><tr>'+''.join('<th>'+E(x)+'</th>' for x in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(x)+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'
stores=[]
for s in d['stores']:
    matches='Not reconciled' if s.get('matched_urls') is None else f"{s['matched_urls']:,} / {s['saved_urls']:,}"
    stores.append([link(s['url'],s['name']),str(s['captured_products']),matches,E(s['status'])+'<p>'+E(s['finding'])+'</p>'])
rankrows=[]
for x in d['ranking']['rows']:
    rankrows.append(f'<tr data-size="{x["size_rank"]}" data-growth="{x["growth_rank"]}"><td>{x["size_rank"]}</td><td><a href="./?ip={E(x["ip"])}">{E(x["name"])}</a></td><td>{x["revenue"]/1000:,.1f}</td><td>{x["prior_revenue"]/1000:,.1f}</td><td>{x["growth_pct"]:+.1f}%</td><td>{x["growth_rank"]}</td></tr>')
candidate_sections=[]
for s in d['stores']:
    cs=[x for x in d['candidates'] if x['source_id']==s['id']]
    if cs:candidate_sections.append('<details><summary>'+E(s['name'])+f' — {len(cs)} broad-rule candidates</summary>'+table(['Candidate listing','Disposition'],[[link(x['url'],x['title']),E(x['disposition'])] for x in cs])+'</details>')
broken=table(['Product','Observed result'],[[link(x['url'],x['name']),'HTTP 404 — historical record retained'] for x in d['product_link_checks'] if x.get('status')==404])
hkex='https://www1.hkexnews.hk/listedco/listconews/sehk/2026/0820/2026082000354_c.pdf#page=30'
h1='https://www.36kr.com/p/3875690969640969'
q3='https://t.cj.sina.com.cn/articles/view/5893582170/15f48ed5a00101b6ec'
cta='https://toy-cta.org/detail?id=37882'
yoyo='https://www.miniso.com/brand/news_207.html'
nommi='https://www3.xinhuanet.com/finance/20260403/8c25846597dd463bbf746f8c80f968ab/c.html'
squish='https://news.zgyww.cn/system/2026/10/23/010308974.shtml'
page='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>China market analysis & source audit · China Toy Atlas</title><meta name="description" content="An external-source review of 18 stores, live assortment differences, and separately scoped revenue, chart-appearance and product-demand evidence."><link rel="stylesheet" href="research.css"><script src="research.js" defer></script><link rel="stylesheet" href="china-intelligence.css?v=1"><script src="catalog.js" defer></script><script src="china-market-data.js?v=1" defer></script><script src="china-intelligence.js?v=1" defer></script></head><body><a class="skip" href="#main">Skip to analysis</a><header><a href="./">← China Toy Atlas</a><nav aria-label="Report sections"><a href="#stores">Store checks</a><a href="#rankings">Rankings</a><a href="#trends">Trends</a><a href="#gaps">Coverage gaps</a></nav></header><main id="main"><section id="chinaIntelligence"></section><details id="auditArchive"><summary>Detailed store audit & historical market comparisons · 31 October 2026</summary>
<div class="eyebrow">EXTERNAL SOURCE REVIEW · 31 OCTOBER 2026 · CHINA TIME</div><h2>What the stores show.<br>What the demand evidence supports.</h2><p class="lede">The catalog is useful for discovery, but its assortment is incomplete and several saved offers have changed. This review checks the external sources, identifies exact discrepancies, and keeps each popularity measure in its proper market and period.</p>
<div class="metrics"><div><b>18</b><span>Store / evidence destinations checked</span></div><div><b>5,679</b><span>Live records read across 12 feeds</span></div><div><b>15</b><span>Saved product links returned 404</span></div><div><b>83</b><span>Variant records with differences</span></div></div>
<aside class="callout"><strong>What “checked” means here</strong><p>Saved URL identities were reconciled against public product feeds, store category pages and selected exact product pages. This is not a manual inspection of all 4,230 product photographs, an authenticity certification, or proof of full mainland assortment. A readable listing is not proof of stock or a completed sale.</p><p>The comparison baseline is the catalog’s 29 October full collection and 30 October detail review. This dated report remains a snapshot even when later weekly refreshes change the live catalog.</p></aside>
<section><h2>Findings that change how to use the catalog</h2><div class="cards"><article><h3>Assortment gaps are real</h3><p>TOYZEROPLUS has 41 direct-store blind-box candidates at its corrected address. Rolife’s figure collection shows 28 items and Molynk’s product pages work, despite zero captured direct-store offers. These are missing source coverage, not evidence of empty stores.</p></article><article><h3>Some saved offers are stale</h3><p>The audit found 38 price differences and 52 stock differences across 83 variant records belonging to 48 products; seven variants changed in both ways. The public catalog applies these exact-offer corrections and marks the 15 broken links as historical with unknown current availability.</p></article><article><h3>Popularity needs several views</h3><p>Use reported IP revenue to compare commercial scale within one company; platform chart appearances for repeated channel visibility; and dated product evidence for specific-series demand. Retailer curation and social views are weaker, different signals.</p></article></div></section>
<section id="stores"><div class="section-label">01 / SOURCE AND ASSORTMENT CHECKS</div><h2>Every tracked store, with the actual coverage boundary</h2><p>“Saved matches” counts listing URLs, not unique designs or physical stock. A product may have several offers. The 12 completed feeds contained 5,679 records; 3,845 saved URLs matched. Heartfelt separately matched all 278 saved category URLs. One additional KikaGoods URL redirected successfully; the official POP MART evidence page was also read.</p><label class="search-label" for="storeSearch">Find a store or issue<input id="storeSearch" type="search" placeholder="Try TOP TOY, maintenance, or missing"></label><div id="storeTable">'''+table(['Store / source','Captured cards','Saved matches','Audit finding'],stores)+'''</div><p id="storeCount" class="small" aria-live="polite">18 sources shown</p>
<details><summary>15 broken product links — exact records</summary>'''+broken+'''<p>404 means the page did not resolve at the check time. It does not establish that the series is discontinued or unavailable elsewhere. Historical prices are retained with their original successful check dates.</p></details>
<details><summary>Price and stock examples — exact variant matters</summary>'''+table(['Store / product','Variant','Before → observed','Interpretation'],[
[link('https://gotoptoy.com/products/nommi-christmas-forest-feast-series-plush-doll-blind-box','TOP TOY · Nommi Christmas Forest Feast'),'One random box','USD 24.99 → 29.99','Still unavailable in the feed; the storefront advertises an upcoming release.'],
[link('https://gotoptoy.com/products/maymei-winter-promise-series-plush-blind-box','TOP TOY · MayMei Winter Promise'),'One random box','USD 19.99 → 29.99','Asking-price change; not a completed transaction.'],
[link('https://gotoptoy.com/products/maymei-greedy-bear-series-plush-doll-blind-box','TOP TOY · MayMei Greedy Bear'),'One random box / set of six','Unavailable → available','Two variant stock changes, not two new products.'],
[link('https://jotoys.store/products/kokosa-different-girls-series-blind-box','JOTOYS · KOKOSA Different Girls'),'Whole set of nine','Unavailable → available','The full set changed; do not apply its stock status to every option.']])+'''<p>All 83 variant differences, original values, exact IDs and sources are in the <a href="source-audit.json" download>audit data download</a>. Prices retain their source currency. Heartfelt’s localized USD display was not treated as a change to its stored HKD offer.</p></details>
<details><summary>What was checked on individual product pages</summary><ul><li><a href="https://toybeta.com/products/twinkle-twinkle-moon-gelato-series-plush-baguette-bag" target="_blank" rel="noopener">ToyBeta Sweet Dreams Forecast</a>: page title and series imagery match the catalog despite the old Moon Gelato slug; no speculative URL replacement.</li><li><a href="https://www.popmart.com/us/products/9170" target="_blank" rel="noopener">POP MART Dip For Fun Squishy Charm</a>: exact series, US release and material evidence checked. The regional date is not a mainland launch.</li><li><a href="https://www.rolifeonline.com/products/rolife-babynanci-surprise-figure-dolls-milk-tea-series-ndxx" target="_blank" rel="noopener">Rolife BabyNanci Milk Tea</a>: six regular designs plus a hidden design described; separate from unrelated DIY kits.</li><li><a href="https://www.molynk.shop/product/the-wishful-bite-cake-squishy-cake" target="_blank" rel="noopener">Molynk Wishful Bite Cake</a>: USD 79.99, Happy Birthday / Love You Forever options. This does not validate the previously excluded, differently named A Piece of Cake record.</li></ul></details></section>
<section id="rankings"><div class="section-label">02 / COMPARABLE RANKINGS</div><h2>Commercial size and growth give different answers</h2><p>Eight artist IPs individually disclosed by POP MART; January–June 2026 versus January–June 2025; global company revenue, all product formats. CNY million. Unaudited company disclosure, not China-only sales, GMV or units. THE MONSTERS includes LABUBU.</p><div class="sort-controls" role="group" aria-label="Ranking order"><button data-rank-sort="size" aria-pressed="true">Order by revenue</button><button data-rank-sort="growth" aria-pressed="false">Order by growth</button></div><div class="table-scroll" tabindex="0"><table id="rankTable"><thead><tr><th>Revenue rank</th><th>IP family</th><th>H1 2026</th><th>H1 2025</th><th>YoY change</th><th>Growth rank</th></tr></thead><tbody>'''+''.join(rankrows)+'''</tbody></table></div><p class="small">Source: '''+link(hkex,'HKEX filing · published 20 August 2026 · printed page 30')+'''. Growth is calculated from disclosed values before rounding. Other artist IPs are grouped and cannot be individually ranked.</p><p><strong>Interpretation:</strong> THE MONSTERS remains largest; Twinkle Twinkle leads growth. A high revenue rank does not imply current acceleration. The same filing reports plush at 57.2% of revenue, growing 60.0%; figures grew 0.3% (printed page 31).</p>
<h3>China platform visibility — a different comparison</h3>'''+table(['Measure / period','Reported leaders','What it means'],[
['Tmall + Douyin chart appearances · H1 2026','1. YOYO 75 · 2. ShyShy 58 · 3. DIMOO 30','Published 26-week study, over 700 samples. Appearance counts may exceed the number of weeks; these are not units or market shares.'],
['Tmall blind-box brand sales · July 2026','MINISO #2 / 3.5% · TOP TOY #4 / 2.9%','Selected disclosed positions only. Missing ranks are not invented; these are brands, not IP-family rankings.']])+'''<p class="small">Sources: '''+link(h1,'三文娱 / 36Kr · 1 July 2026')+'; '+link(cta,'China Toy Association · July Tmall data, review dated 15 September 2026')+'''. The publisher’s raw weekly transactions were not independently re-audited.</p>
<h3>Useful milestones that should remain unranked</h3>'''+table(['IP','Metric and period','Boundary'],[
['YOYO','Global GMV above CNY 1 billion · January–September 2026','MINISO announcement as of 1 October; company-reported GMV, not POP MART-style revenue. '+link(yoyo,'Primary announcement')],
['Nommi','Reported sales above CNY 200 million · full-year 2025','Different year and unspecified geographical split; not comparable with H1 2026 revenue. '+link(nommi,'China Securities Journal / Xinhua · 3 April 2026')]])+'''</section>
<section id="trends"><div class="section-label">03 / PRODUCT DEMAND AND EMERGING THEMES</div><h2>What is trending, and how strong is the evidence?</h2><h3>Q3 product demand: a threshold group, not a 1–7 ranking</h3><p>三文娱’s 13-week Tmall/Douyin review identifies seven series whose sampled pages displayed sales counters above 100,000: SpongeBob Residents of Bikini Bottom, CRYBABY Vacation Mode On, Twinkle Twinkle 怦然星动, YOYO 萌趣歪头, Twinkle Twinkle Sweet Dreams Forecast, DIMOO 新生日记 and DIMOO Secret Theater.</p><p>These are page-displayed totals observed in Q3, not verified incremental Q3 units. Limited auctions and releases absent from charts can be missed. The same study describes lower-threshold demand for Heyone’s 心动狂欢4.0 / 星梦奇缘2.0 and TNT SPACE’s Rayan 无垠跳动, DORA 甜酷警告 and Zoraa 糖果过家家mini. Exact series translation and SKU matching are needed before transferring a signal to a catalog card.</p><p class="small">'''+link(q3,'三文娱 on Sina · 8 October 2026')+'''. Its 36Kr republication is the same study, not a second independent source.</p><p><strong>Analyst implication:</strong> Maintain established-series coverage and restock tracking alongside new releases. A new product page alone is insufficient evidence of popularity.</p>
<div class="cards"><article><h3>Retailer picks: discovery signals</h3><p>TOP TOY’s Best Sellers page describes a handpicked collection and opens with featured sorting. KikaGoods Hot Sale mixes toy products with accessories. JOTOYS also uses a Best Sellers label. These observations support retailer merchandising signals; they do not establish numerical nationwide ranks.</p><p>'''+link('https://gotoptoy.com/collections/best-sellers','TOP TOY')+' · '+link('https://www.kikagoods.com/collections/hot-sale-1','KikaGoods')+' · '+link('https://jotoys.store','JOTOYS')+'''</p></article><article><h3>Specialist squishy demand</h3><p>Heartfelt’s Hot / Viral collection includes Lisa Jumbo Snowman, Labuladuo Scarf Rabbit and 3AN Cow Print Sticky Bun, alongside compilations and proxy-shopping pages. Keep named items separate from services. No public unit volumes or national ordering were established.</p><p>'''+link('https://heartfeltsquishy.shoplineapp.com/categories/hot-items-viral-on-social-media','Observed retailer collection · 31 October')+'''</p></article><article><h3>Wax-shell squishies: emerging attention</h3><p>Local reporting cites 340 million Xiaohongshu topic views as of 22 October and interviews sellers of crackling wax-shell squishies. One shop quoted CNY 10–80 retail; another offered a 12-piece blind set for CNY 88. These are observations, not national average prices or buyer counts.</p><p><strong>Analyst implication:</strong> Evaluate sound-plus-touch appeal alongside breakage, temperature sensitivity and repeat use. Social reach alone cannot establish profitable demand.</p><p>'''+link(squish,'China Yiwu News · 23 October 2026')+'''</p></article></div>
<h3>How to use this evidence in assortment decisions</h3>'''+table(['Decision','Evidence to use','What still needs validation'],[
['Maintain established character coverage','Comparable disclosed scale and repeated platform visibility','China-market SKU availability, current local price, exact series and pack.'],
['Evaluate plush and portable formats','Company format mix plus specific product evidence','Whether a pendant, mini, articulated doll or large display item fits the intended customer.'],
['Expand emerging brands selectively','Named series in published channel studies and direct product pages','Do not assign a brand-wide campaign total to each product. Finding Unicorn, Heyone and TNT SPACE lack a comparable global revenue table here.'],
['Explore tactile squishies','Specialist stockists, exact-maker products and dated local reporting','PU, silicone and consumable wax-shell products have different use and shipping requirements; materials must be product-specific.'],
['Prioritize source coverage fixes','Readable missing direct stores and verified new listing candidates','Confirm images, maker/IP attribution, random versus confirmed selection and single versus set before import.']])+'''<p>These are research priorities, not statistically estimated demand forecasts or purchasing-volume recommendations.</p></section>
<section id="gaps"><div class="section-label">04 / WHAT REMAINS INCOMPLETE</div><h2>Coverage gaps, without inflating the totals</h2><p>The audit found 153 listings caught by a broad keyword rule outside the saved URL set. That is <strong>not 153 missing toys</strong>: 83 belong to ANTHILL’s intentionally wider assortment, some are bags, clothes or a bundle, and one is a renamed page. Candidates remain outside the core product count until reviewed.</p>'''+''.join(candidate_sections)+'''
<h3>Remaining data limitations</h3>'''+table(['Catalog field at audit baseline','Available','Practical limit'],[
['Mainland release evidence','13 / 4,230 records','Overseas listing dates cannot fill the gap.'],
['Documented China price','12 / 4,230','No currency conversion is presented as a mainland selling price.'],
['Product-level unit-sales field','0 / 4,230','Published chart thresholds are retained in this analysis; no falsely precise SKU units are added.'],
['Specifications / dimensions','2,459 / 1,713 records','Missing material, size, regular/secret counts and odds remain unknown.'],
['Saved variant options','3,948 records','Variants are offers, not additional product series.'],
['Individually visually reviewed series','8 highlighted samples','Feed matching does not expand the visual-review claim.']])+'''<p>The 778 brand/source labels are not 778 independently validated manufacturers. Imported/licensed characters remain distinguishable from Chinese original IP. Neither source listing counts nor the number of cards is used as a popularity rank.</p>
<h3>Maintenance rules</h3><p>Weekly collection uses the corrected TOYZEROPLUS address. The dated correction step preserves newer observations and never turns a failed link check into a fresh successful price check. Future source checks should retain HTTP status, final URL, exact variant ID, currency, pack size and evidence period. This report’s market statistics do not automatically become “this week’s sales” during a refresh.</p><div class="downloads"><a href="source-audit.json" download>Download detailed audit JSON</a><a href="./">Return to product catalog</a><a href="https://github.com/royhei-cpu/royhei-cpu.github.io/tree/main/china-toys">Review source and maintenance code ↗</a></div></section></details></main><footer>China Toy Atlas · External audit observed 31 October 2026, Asia/Shanghai · Historical snapshot; open source links for later changes.</footer></body></html>'''
(R/'research.html').write_text(page)
compact={k:d[k] for k in ('checked','summary','stores','product_link_checks')}
(R/'source-audit-data.js').write_text('window.ATLAS_SOURCE_AUDIT='+json.dumps(compact,ensure_ascii=False,separators=(',',':'))+';\n')
print('Built research.html and source-audit-data.js')

